// Decode one OCPP-J frame.  解码一帧 OCPP-J。
// Frame types / 帧类型:  [2,uid,action,payload] CALL
//                        [3,uid,payload]        CALLRESULT
//                        [4,uid,code,desc,{}]   CALLERROR
let frame;
try {
    frame = JSON.parse(msg.payload);
} catch (e) {
    node.error("not a JSON frame: " + msg.payload, msg);
    return null;
}
if (!Array.isArray(frame) || frame.length < 2) {
    node.error("not an OCPP-J frame", msg);
    return null;
}

const type = frame[0];
msg.ocpp = { type: type, uid: frame[1], action: "", payload: {} };

if (type === 2) {
    msg.ocpp.action = frame[2];
    msg.ocpp.payload = frame[3] || {};
} else if (type === 3) {
    msg.ocpp.payload = frame[2] || {};
    // Correlate with the request we sent, so we can label the reply.
    // 与我们发出的请求关联，这样才能给响应打上标签。
    const pending = flow.get("pending") || {};
    msg.ocpp.action = pending[msg.ocpp.uid] || "";
    delete pending[msg.ocpp.uid];
    flow.set("pending", pending);
} else if (type === 4) {
    msg.ocpp.errorCode = frame[2];
    msg.ocpp.errorDescription = frame[3];
}

node.status({ fill: "green", shape: "dot", text: (msg.ocpp.action || "type " + type) });
return msg;

// Answer a CALL from the charge point.  回应充电桩发来的 CALL。
// Only type 2 needs a reply.  只有 type 2 需要回复。
if (msg.ocpp.type !== 2) { return null; }

const now = new Date().toISOString();
const action = msg.ocpp.action;
const p = msg.ocpp.payload;
const whitelist = flow.get("whitelist") || ["DEADBEEF", "CAFEBABE"];
let result;

switch (action) {
    case "BootNotification":
        // interval is the heartbeat period we impose on the station.
        // interval 是我们强加给桩的心跳周期。
        result = { currentTime: now, interval: 30, status: "Accepted" };
        break;

    case "Heartbeat":
        result = { currentTime: now };
        break;

    case "StatusNotification":
        flow.set("connectorStatus", p.status);
        result = {};
        break;

    case "Authorize": {
        const ok = whitelist.indexOf(p.idTag) !== -1;
        result = { idTagInfo: { status: ok ? "Accepted" : "Invalid" } };
        break;
    }

    case "StartTransaction": {
        const txId = (flow.get("nextTxId") || 0) + 1;
        flow.set("nextTxId", txId);
        flow.set("activeTx", txId);
        result = { transactionId: txId, idTagInfo: { status: "Accepted" } };
        break;
    }

    case "StopTransaction":
        flow.set("activeTx", null);
        result = {};
        break;

    case "MeterValues":
    case "DiagnosticsStatusNotification":
    case "FirmwareStatusNotification":
        result = {};
        break;

    default:
        // Never stay silent. An unanswered CALL trips the station's 30 s
        // message timeout and drops the whole session.
        // 绝不能沉默。没有响应的 CALL 会触发桩侧 30 秒超时并断开整个会话。
        msg.payload = JSON.stringify([4, msg.ocpp.uid, "NotImplemented",
                                      "no handler in this flow", {}]);
        node.warn("unhandled action: " + action);
        return msg;
}

msg.payload = JSON.stringify([3, msg.ocpp.uid, result]);
return msg;

// Flatten every frame into one telemetry record.
// 把每一帧压平成一条遥测记录。
// This is the shape the dashboard and the JSONL log both consume.
// 仪表盘和 JSONL 日志消费的都是这个结构。
const o = msg.ocpp;
const rec = {
    ts: new Date().toISOString(),
    type: o.type,
    uid: o.uid,
    action: o.action || "",
    status: flow.get("connectorStatus") || "Unknown",
    tx: flow.get("activeTx") || null,
    power_w: null,
    current_a: null,
    energy_wh: null
};

if (o.action === "MeterValues") {
    const samples = ((o.payload.meterValue || [])[0] || {}).sampledValue || [];
    samples.forEach(function (s) {
        const v = parseFloat(s.value);
        if (s.measurand === "Power.Active.Import") { rec.power_w = v; }
        else if (s.measurand === "Current.Import") { rec.current_a = v; }
        else if (!s.measurand || s.measurand === "Energy.Active.Import.Register") { rec.energy_wh = v; }
    });
}

if(o.action == "StatusNotification"){
    rec.error_code = o.payload.errorCode || "NoError";
}
if (o.type === 4) { rec.error = o.errorCode + ": " + o.errorDescription; }

msg.payload = rec;
msg.topic = rec.action;


if (rec.current_a !== null) { flow.set("lastCurrent", rec.current_a); 
  } else if (rec.status !== "Charging") {
    // No reading and not charging: the current really is zero. Without
    // this the last value sticks, and anything reading the state — the
    // scenario assertions, not just the gauge — sees a station still
    // drawing 6 A after it stopped.
    // 没有读数且不在充电: 电流确实是 0。不写这一句, 最后那个值会一直挂着,
    // 而读状态的东西——不只是仪表盘, 还有场景断言——会看到一台已经停止
    // 却还在取 6 A 的桩。
    flow.set("lastCurrent", 0);
}

return msg;

// CSMS -> station: start a transaction remotely.
// 后台 -> 桩: 远程开启事务。
const uid = "op-" + ((flow.get("opSeq") || 0) + 1);
flow.set("opSeq", (flow.get("opSeq") || 0) + 1);

const pending = flow.get("pending") || {};
pending[uid] = "RemoteStartTransaction";
flow.set("pending", pending);

msg.payload = JSON.stringify([2, uid, "RemoteStartTransaction", { idTag: "DEADBEEF" }]);
return msg;

const tx = flow.get("activeTx");
if (!tx) { node.warn("no active transaction | 当前没有进行中的事务"); return null; }

const uid = "op-" + ((flow.get("opSeq") || 0) + 1);
flow.set("opSeq", (flow.get("opSeq") || 0) + 1);

const pending = flow.get("pending") || {};
pending[uid] = "RemoteStopTransaction";
flow.set("pending", pending);

msg.payload = JSON.stringify([2, uid, "RemoteStopTransaction", { transactionId: tx }]);
return msg;

// The message this whole lab is about: curtail the station.
// 整个实验室的核心消息: 对充电桩限功率。
//
// msg.limit lets one inject node serve several buttons.
// msg.limit 让一个 function 节点服务多个按钮。
const limit = (msg.limit !== undefined) ? Number(msg.limit)
              : (msg.payload !== undefined && msg.payload !== "") ? Number(msg.payload)
              : 16;

const uid = "op-" + ((flow.get("opSeq") || 0) + 1);
flow.set("opSeq", (flow.get("opSeq") || 0) + 1);

const pending = flow.get("pending") || {};
pending[uid] = "SetChargingProfile";
flow.set("pending", pending);

msg.payload = JSON.stringify([2, uid, "SetChargingProfile", {
    connectorId: 1,
    csChargingProfiles: {
        chargingProfileId: 200,
        stackLevel: 2,
        chargingProfilePurpose: "TxProfile",
        chargingProfileKind: "Relative",
        chargingSchedule: {
            chargingRateUnit: "A",
            chargingSchedulePeriod: [{ startPeriod: 0, limit: limit }]
        }
    }
}]);

node.status({ fill: "blue", shape: "ring", text: "sent " + limit + " A" });
return msg;

// ── run scenario · On Message ────────────────────────────────────────
// One-button bench test: start, assert full power, curtail, assert the
// curtailment took, stop, assert zero. Outputs:
//   1 start   2 curtail   3 stop   4 results
// 一键台架测试: 启动 → 断言满功率 → 限流 → 断言限流生效 → 停止 → 断言归零。
// 输出口: 1 启动  2 限流  3 停止  4 结果

// Refuse to start a second run on top of a live one: two sequences would
// interleave their commands and both would report nonsense.
// 已有一轮在跑时拒绝重入: 两个序列的指令会交错, 两边的结果都是垃圾。
if (context.get("running")) {
    node.warn("test already running, ignoring");
    return null;
}
context.set("running", true);

const results = [];
const timers = [];
const cur = () => flow.get("lastCurrent");

function assert(name, want) {
    const got = cur();
    const ok = (got === want);
    results.push(`${ok ? "PASS" : "FAIL"}  ${name}  expected=${want} got=${got}`);
    node.status({ fill: ok ? "green" : "red", shape: "dot", text: name });
}

function at(ms, fn) { timers.push(setTimeout(fn, ms)); }

node.status({ fill: "blue", shape: "ring", text: "running..." });

// t=0 — start charging
node.send([{ payload: "" }, null, null, null]);

// Assertions sit 15 s behind their command on purpose. The station has to
// receive it, apply it, and reach its next 5 s metering tick before the
// change is observable. Asserting immediately would always fail.
// 断言刻意落后指令 15 秒。桩要收到、执行、并等到下一个 5 秒计量周期，变化才
// 观察得到。紧跟着断言必然失败。
at(15000, () => assert("charging at full power", 32));
at(20000, () => node.send([null, { payload: 6 }, null, null]));
at(35000, () => assert("curtailed to 6 A", 6));
at(40000, () => node.send([null, null, { payload: "" }, null]));
at(50000, () => {
    assert("stopped", 0);
    const failed = results.filter(r => r.startsWith("FAIL")).length;
    node.status({
        fill: failed ? "red" : "green", shape: "dot",
        text: failed ? `${failed} FAILED` : "all passed"
    });
    node.send([null, null, null, { payload: results.join("\n") }]);
    context.set("running", false);
});

context.set("timers", timers);
return null;

finalize:
// ── run scenario · On Stop ───────────────────────────────────────────
// Timers outlive the node. A redeploy mid-run destroys and rebuilds this
// node, but any setTimeout still pending fires into the dead one and
// Node-RED logs "Function tried to send a message but the node is no
// longer active". Same shape as an orphaned asyncio task: background work
// has to be cancelled with the thing that started it.
// 定时器的寿命长于节点。测试跑到一半重新 Deploy 会销毁并重建本节点，而尚未
// 触发的 setTimeout 仍会向那个已死的节点发消息，Node-RED 会报
// "the node is no longer active"。这和游离的 asyncio 任务是同一个形状:
// 后台工作必须和启动它的东西一起被取消。
(context.get("timers") || []).forEach(clearTimeout);
context.set("timers", []);
context.set("running", false);
